INSERT INTO kn_posts (lang, slug, title, excerpt, content, status, published_at, category_id, featured_image, meta_title, meta_description, og_image)
SELECT 'fr', 'nettoyage-fin-de-leasing-voiture', 'Nettoyage de fin de leasing ou avant vente : préparer sa voiture', 'Fin de leasing ou vente de votre voiture : comment éviter les frais de remise en état et la présenter dans un état proche du neuf ? Check-list en 5 étapes et conseils.', '[{"type":"text","bg":"white","html":"<p><strong>Votre contrat de leasing touche à sa fin, ou vous mettez votre voiture en vente ? Son état de propreté pèse plus lourd que vous ne le pensez.</strong> À la restitution, le loueur compare le véhicule à son état d\'origine et peut facturer des frais si l\'intérieur ou l\'extérieur ne sont pas irréprochables. À la revente, une voiture impeccable se vend plus facilement et inspire confiance. Voici comment bien préparer votre véhicule, étape par étape.</p><h2 class=\\"kn-subtitle\\">L\'essentiel en un coup d\'œil</h2><ul class=\\"kn-checklist\\"><li><strong>Pourquoi :</strong> éviter les frais de remise en état à la restitution, ou mieux vendre votre véhicule.</li><li><strong>Quand :</strong> idéalement quelques jours avant la restitution ou la mise en vente.</li><li><strong>Comment :</strong> un nettoyage intérieur et extérieur à la main, directement chez vous.</li><li><strong>Paiement :</strong> uniquement après la prestation.</li></ul>","visible":["desktop","tablet","mobile"]},{"type":"prestation","bg":"cream","eyebrow":"POURQUOI NETTOYER","h2":"Évitez les frais de fin de leasing !","intro":"Des frais de nettoyage peuvent s\'ajouter si vous ne respectez pas l\'état d\'origine de la voiture. Rendre un véhicule dans un état irréprochable, c\'est la meilleure façon de clôturer son contrat sereinement.","columns":"2","items":[{"title":"Pas de mauvaise surprise","desc":"Un véhicule propre limite le risque de facturation de remise en état à la restitution."},{"title":"Un état proche du neuf","desc":"Intérieur et extérieur remis à neuf, jusqu\'aux détails qui se remarquent."},{"title":"Gain de temps","desc":"Nous venons à vous : vous n\'avez ni lavage ni déplacement à organiser."},{"title":"Une meilleure revente","desc":"Une voiture soignée se présente mieux aux acheteurs et se négocie plus facilement."}],"visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Pourquoi est-il préférable de nettoyer son véhicule en fin de leasing ?</h2><p>Le contrat de leasing prévoit que le véhicule soit restitué dans un état conforme à son état d\'origine, usure normale mise à part. Taches sur les sièges, moquettes sales, plastiques ternes ou jantes encrassées sont autant de points que le loueur peut relever lors de l\'inspection.</p><p>Avec Keepnew, vous rendez votre véhicule de leasing dans un état irréprochable. Notre nettoyage comprend :</p><ul class=\\"kn-checklist\\"><li>Le <strong>nettoyage intérieur et extérieur à la main</strong>.</li><li>Le <strong>shampoing des moquettes</strong>.</li><li>Le <strong>nettoyage des sièges</strong>.</li><li>Le <strong>traitement des plastiques</strong>.</li><li>Le <strong>nettoyage des jantes</strong>.</li></ul><p>L\'échéance de votre leasing approche ? Prenez rendez-vous en ligne dès maintenant pour une remise à neuf de votre véhicule.</p>","visible":["desktop","tablet","mobile"]},{"type":"how","bg":"alt","columns":"3","eyebrow":"LA CHECK-LIST","h2":"Comment préparer la restitution de votre véhicule en 5 étapes","steps":[{"title":"Rassemblez les documents et accessoires","body":"Avant le nettoyage, réunissez tout ce qui a été fourni avec le véhicule : manuels, clés de rechange et accessoires d\'origine (tapis, cric, roue de secours…)."},{"title":"Vérifiez l\'état général","body":"Contrôlez la carrosserie (bosses, rayures), les pneus et les jantes, le fonctionnement des feux et l\'intérieur (taches, déchirures, usure)."},{"title":"Petites réparations et entretien","body":"Faites reprendre les petits impacts de peinture et rayures, contrôlez l\'usure et la pression des pneus ainsi que les niveaux."},{"title":"Dépersonnalisez","body":"Retirez vos effets personnels et les ajouts posés après l\'achat : autocollants, désodorisants, accessoires supplémentaires."},{"title":"Faites appel à Keepnew","body":"Réservez en ligne ou contactez-nous : nous remettons le véhicule dans un état proche du neuf avant la restitution."}],"visible":["desktop","tablet","mobile"]},{"type":"domicile-vs-atelier","bg":"white","eyebrow":"DEUX SITUATIONS","h2":"Fin de leasing ou vente : à quoi faut-il penser ?","home_title":"Restitution de leasing","home_icon":"shield","home_desc":"L\'objectif : rendre un véhicule conforme à l\'état d\'origine.","home_items":[{"icon":"check","label":"Intérieur propre, sans taches ni odeurs"},{"icon":"check","label":"Sièges et moquettes nettoyés"},{"icon":"check","label":"Plastiques et jantes soignés"},{"icon":"check","label":"Accessoires d\'origine présents"},{"icon":"check","label":"Aucun ajout personnel (autocollants, désodorisants)"}],"workshop_title":"Vente du véhicule","workshop_icon":"sparkles","workshop_desc":"L\'objectif : donner envie et rassurer l\'acheteur.","workshop_items":[{"icon":"check","label":"Une première impression impeccable"},{"icon":"check","label":"Habitacle neutre, sans odeurs"},{"icon":"check","label":"Carrosserie brillante et jantes propres"},{"icon":"check","label":"Photos d\'annonce plus flatteuses"},{"icon":"check","label":"Une meilleure base de négociation"}],"workshop_note":"Pour une carrosserie qui ressort vraiment, un polissage en atelier peut compléter le nettoyage.","visible":["desktop","tablet","mobile"]},{"type":"text","bg":"white","html":"<h2 class=\\"kn-subtitle\\">Nos conseils pour une restitution sans surprise</h2><ul class=\\"kn-checklist\\"><li><strong>Relisez votre contrat :</strong> les critères d\'état attendus y sont décrits (usure normale, kilométrage, accessoires).</li><li><strong>Anticipez :</strong> prévoyez le nettoyage quelques jours avant la date de restitution, pour laisser le temps d\'éventuelles retouches.</li><li><strong>Photographiez le véhicule</strong> une fois propre : vous gardez une preuve de son état au moment de la remise.</li><li><strong>Assistez à l\'état des lieux</strong> si possible, pour discuter immédiatement d\'éventuelles remarques.</li><li><strong>Ne négligez pas les détails :</strong> coffre, seuils de portes, vide-poches et jantes sont souvent examinés.</li></ul>","visible":["desktop","tablet","mobile"]},{"type":"seo-content","bg":"rose","h2":"Vous êtes un professionnel ?","body":"<p>Pour le nettoyage régulier de votre flotte ou de votre voiture de leasing professionnelle, contactez-nous pour une offre sur mesure : abonnement flexible, facturation HTVA et intervention directement sur votre lieu de travail.</p><p><a href=\\"/offre-professionnelle-de-nettoyage-voiture-entreprises-independants\\">Découvrir notre offre entreprises et indépendants</a></p>","cta_label":"Demander une offre sur mesure","cta_style":"primary","cta_align":"left","visible":["desktop","tablet","mobile"]},{"type":"accordion","bg":"white","eyebrow":"FAQ","h2":"Vos questions sur le nettoyage de fin de leasing","items":[{"q":"Pourquoi nettoyer sa voiture avant la restitution du leasing ?","a":"Des frais de nettoyage peuvent être facturés si le véhicule n\'est pas rendu dans l\'état d\'origine. Un nettoyage complet limite ce risque."},{"q":"Que comprend le nettoyage de fin de leasing ?","a":"Un nettoyage intérieur et extérieur à la main, le shampoing des moquettes, le nettoyage des sièges, le traitement des plastiques et le nettoyage des jantes."},{"q":"Quand faut-il réserver ?","a":"Idéalement quelques jours avant la date de restitution, pour pouvoir faire reprendre d\'éventuels défauts."},{"q":"Intervenez-vous chez moi ou sur mon lieu de travail ?","a":"Oui, nous nous déplaçons à domicile et sur votre lieu de travail en province de Liège, à Namur et dans le Luxembourg belge."},{"q":"Le nettoyage est-il utile si je vends ma voiture ?","a":"Oui : un véhicule propre et sans odeurs se présente mieux, rassure l\'acheteur et facilite la négociation."},{"q":"Pouvez-vous reprendre rayures et petits impacts ?","a":"Le nettoyage ne corrige pas les rayures. Pour les micro-rayures et la brillance, nous proposons un polissage en atelier à Visé."},{"q":"Quand dois-je payer ?","a":"Vous payez uniquement après la prestation."}],"visible":["desktop","tablet","mobile"]},{"type":"reviews","bg":"cream","eyebrow":"ILS NOUS FONT CONFIANCE","h2":"Ce que disent nos clients","visible":["desktop","tablet","mobile"]},{"type":"cta-final","bg":"blue","eyebrow":"FIN DE LEASING","title":"Rendez votre véhicule <span class=\\"hl-inverse\\">dans un état neuf</span>","cta_title":"Prenez RDV en ligne","phone":"+32 (0)4 55 13 84 19","visible":["desktop","tablet","mobile"]}]', 'draft', NULL, (SELECT id FROM kn_categories WHERE slug = 'conseils-entretien' AND lang = 'fr' LIMIT 1), NULL, 'Nettoyage fin de leasing et avant vente voiture | Keepnew', 'Évitez les frais de fin de leasing et mieux vendre votre voiture : check-list en 5 étapes, nettoyage intérieur et extérieur à domicile à Liège et Namur.', NULL
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM kn_posts WHERE slug = 'nettoyage-fin-de-leasing-voiture' AND lang = 'fr');
